def word_break(s, word_dict):
    words = set(word_dict)
    dp = [False] * (len(s) + 1)  # dp[i]: the first i characters can be segmented
    dp[0] = True
    for i in range(1, len(s) + 1):
        for j in range(i):
            if dp[j] and s[j:i] in words:
                dp[i] = True
                break
    return dp[len(s)]
